function parse(line: string): Piece {
  const [id, name, culture, kindRaw, , period, material, place, museum, blurb, image] = line.split("|");
  const kind = (kindRaw as PieceKind) ?? "piece";
  return {
    id: id ?? "",
    name: name ?? "",
    culture: (culture as Culture) ?? "eg",
    kind,
    value: id === "tut-mask" ? 5 : kind === "god" ? 10 : kind === "king" ? 5 : 1,
    period: period ?? "",
    material: material ?? "",
    place: place ?? "",
    museum: museum ?? "",
    blurb: blurb ?? "",
    image: image || `/cards/${id}.jpg`,
  };
}

export const PIECES: Piece[] = RAW.trim()
  .split("\n")
  .filter(Boolean)
  .map(parse)
  .filter((piece) => piece.culture === "eg");

const BY_ID = new Map(PIECES.map((piece) => [piece.id, piece]));

export function pieceById(id: string): Piece {
  const piece = BY_ID.get(id);
  if (!piece) throw new Error(`unknown piece ${id}`);
  return piece;
}

export const CULTURE_NAME: Record<Culture, string> = {
  eg: "مصرية",
  gr: "يونانية",
  is: "إسلامية",
};

export const KIND_NAME: Record<PieceKind, string> = {
  god: "معبود",
  king: "ملك",
  piece: "قطعة",
};
